from classes.common import *  # noqa: F401,F403

SONG = School("Song", "#ff9ce0", "#ffe8f7", fleck="note", fleck2="star", projectile="ArcanumAscendant/Vfx/Note")
SKALD = School("Song", "#ff8a4a", "#ffe0b0", fleck="note", fleck2="spark", projectile="ArcanumAscendant/Vfx/Note")
