        Node("Inspire", None, (5, 3), kind="Spell", spell="Inspire", pre=["Anthem", "Soothing"]),
        Node("Earworm", "earworm", (0, 4), kind="Notable", pre=["Drowsy"], mods=[burst_on("AA_Concussed", 0.25, 1.0, tag="Song")]),
