        Node("Maestro", "maestro", (5, 5), ranks=3, pre=["Encore", "Virtuoso"], stats={"AA_ManaMax": 15}),
        Node("BalladOfHeroes", None, (3, 6), kind="Spell", spell="BalladOfHeroes", pre=["Chorus", "Muse", "Maestro"]),
